open(P+'.py','w').write('''def transform(grid):
    h,w=len(grid),len(grid[0])
    def lines(idx,trans):
        full=[]
        for i in idx:
            vals={grid[i][j] for j in range(w)} if not trans else {grid[j][i] for j in range(h)}
            if len(vals)==1 and 0 not in vals: full.append(i)
        keep=[];prev=None
        for i in idx:
            if i in full: keep.append(i)
            elif prev is None or prev in full: keep.append(i)
            prev=i
        return keep
    rows=lines(range(h),False); cols=lines(range(w),True)
    return [[grid[r][c] for c in cols] for r in rows]
''')
